SELECT CASE WHEN stores.sqft >= 16451 THEN 'high' WHEN stores.sqft >= 2636 THEN 'mid' ELSE 'low' END AS sqft_bucket, MAX(store_sales.units) - MIN(store_sales.units) AS units_range, MAX(store_sales.sale_date) AS last_sale_date FROM store_sales INNER JOIN stores ON store_sales.store_id = stores.id WHERE store_sales.product_id IN (1, 4, 9) GROUP BY CASE WHEN stores.sqft >= 16451 THEN 'high' WHEN stores.sqft >= 2636 THEN 'mid' ELSE 'low' END;
